// ConsultaTipo devolve os metadados de um tipo de consulta.
func ConsultaTipo(tipo string) (ConsultaTipoMeta, bool) {
	meta, ok := ConsultaTipos[tipo]
	return meta, ok
}

// ServiceActionsFor devolve as actions documentadas de um serviço.
func ServiceActionsFor(service string) []string {
	return ServiceActions[service]
}

// HasAction informa se uma action é documentada para o serviço.
func HasAction(service, action string) bool {
	for _, candidate := range ServiceActions[service] {
		if candidate == action {
			return true
		}
	}
	return false
}
